using Alterverse.Combat;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Match
{
public sealed class DimensionPlanetDirector:MonoBehaviour
{
private const float FirstSpawn=120f,SecondSpawn=330f,ThirdSpawn=510f,Warning=15f;private static DimensionPlanetDirector active;private float elapsed;private bool warnedFirst,warnedSecond,warnedThird,spawnedFirst,spawnedSecond,spawnedThird;private DimensionsFront front;public static string Announcement{get;private set;}public static float AnnouncementUntil{get;private set;}public static float FirstSpawnRemaining=>Mathf.Max(0,FirstSpawn-(active!=null?active.elapsed:FirstSpawn));public static float SecondSpawnRemaining=>Mathf.Max(0,SecondSpawn-(active!=null?active.elapsed:SecondSpawn));public static float ThirdSpawnRemaining=>Mathf.Max(0,ThirdSpawn-(active!=null?active.elapsed:ThirdSpawn));private void Awake(){active=this;elapsed=0;warnedFirst=warnedSecond=warnedThird=spawnedFirst=spawnedSecond=spawnedThird=false;Announcement=null;AnnouncementUntil=0;front=FindAnyObjectByType<DimensionsFront>();}private void OnDestroy(){if(active==this){active=null;Announcement=null;AnnouncementUntil=0;}}
private void Update(){if(Time.timeScale<=0f)return;if(front==null)front=FindAnyObjectByType<DimensionsFront>();if(front!=null&&front.HasEnded)return;elapsed+=Time.deltaTime;if(!warnedFirst&&elapsed>=FirstSpawn-Warning){warnedFirst=true;Announce("FLUX PLANET SPAWNS IN 15 SECONDS — CENTER FRONT");}if(!spawnedFirst&&elapsed>=FirstSpawn){spawnedFirst=true;SpawnPlanet("DF_FluxPlanet",new Vector3(0,1.25f,3.2f),PlanetBuffType.Flux,320,StylizedArtDirection.LumenEnergy,0);Announce("FLUX PLANET ACTIVE — CENTER FRONT");}if(!warnedSecond&&elapsed>=SecondSpawn-Warning){warnedSecond=true;Announce("GUARD PLANET IN 15 SECONDS — METEOR STORM • CENTER FRONT");}if(!spawnedSecond&&elapsed>=SecondSpawn){spawnedSecond=true;SpawnPlanet("DF_GuardPlanet",new Vector3(0,1.25f,-3.2f),PlanetBuffType.Guard,900,StylizedArtDirection.WarmAccent,1);Announce("GUARD PLANET ACTIVE — METEOR SHOWER • WATCH THE IMPACT ZONES");}if(!warnedThird&&elapsed>=ThirdSpawn-Warning){warnedThird=true;Announce("FINAL FLUX PLANET SPAWNS IN 15 SECONDS — CENTER FRONT");}if(!spawnedThird&&elapsed>=ThirdSpawn){spawnedThird=true;SpawnPlanet("DF_FinalFluxPlanet",new Vector3(0,1.25f,10f),PlanetBuffType.Flux,460,StylizedArtDirection.LumenEnergy,2);Announce("FINAL FLUX PLANET ACTIVE — CENTER FRONT");}}
private static void Announce(string text){Announcement=text;AnnouncementUntil=Time.unscaledTime+4f;}private static void SpawnPlanet(string name,Vector3 p,PlanetBuffType type,float hp,Color color,int variant){GameObject root=GameObject.CreatePrimitive(PrimitiveType.Sphere);root.name=name;GameObject world=GameObject.Find("DF_MatchWorld");if(world!=null)root.transform.SetParent(world.transform,true);root.transform.position=p;root.transform.localScale=Vector3.one*(variant==2?1.82f:1.65f);Renderer r=root.GetComponent<Renderer>();if(r!=null)r.material.color=Color.Lerp(color,Color.black,.18f);GameObject atmosphere=GameObject.CreatePrimitive(PrimitiveType.Sphere);atmosphere.name="DF_PlanetAtmosphere";atmosphere.transform.SetParent(root.transform,false);atmosphere.transform.localScale=Vector3.one*1.16f;Collider ac=atmosphere.GetComponent<Collider>();if(ac!=null)ac.enabled=false;Renderer ar=atmosphere.GetComponent<Renderer>();if(ar!=null)ar.material.color=new Color(color.r,color.g,color.b,.34f);GameObject ring=GameObject.CreatePrimitive(PrimitiveType.Cylinder);ring.name="DF_PlanetRing";ring.transform.SetParent(root.transform,false);ring.transform.localScale=variant==1?new Vector3(2.05f,.045f,2.05f):new Vector3(1.85f,.035f,1.85f);ring.transform.localRotation=Quaternion.Euler(type==PlanetBuffType.Guard?68f:74f,0,18f);Collider rc=ring.GetComponent<Collider>();if(rc!=null)rc.enabled=false;Renderer rr=ring.GetComponent<Renderer>();if(rr!=null)rr.material.color=Color.Lerp(color,Color.white,.35f);for(int i=0;i<8;i++){GameObject shard=GameObject.CreatePrimitive(i%2==0?PrimitiveType.Cube:PrimitiveType.Sphere);shard.name="DF_PlanetShard";shard.transform.SetParent(root.transform,false);float a=i*Mathf.PI*.25f;float orbit=1.45f+(i%3)*.12f;shard.transform.localPosition=new Vector3(Mathf.Cos(a)*orbit,Mathf.Sin(i*1.7f)*.42f,Mathf.Sin(a)*orbit);shard.transform.localScale=i%2==0?new Vector3(.12f,.48f,.12f):Vector3.one*.18f;shard.transform.rotation=Quaternion.Euler(25,i*47,25);Collider c=shard.GetComponent<Collider>();if(c!=null)c.enabled=false;Renderer sr=shard.GetComponent<Renderer>();if(sr!=null)sr.material.color=color;}if(variant==1){for(int i=0;i<3;i++){GameObject moon=GameObject.CreatePrimitive(PrimitiveType.Sphere);moon.name="DF_GuardMoon";moon.transform.SetParent(root.transform,false);float ma=i*Mathf.PI*2f/3f;moon.transform.localPosition=new Vector3(Mathf.Cos(ma)*2.05f,.55f+Mathf.Sin(ma)*.35f,Mathf.Sin(ma)*2.05f);moon.transform.localScale=Vector3.one*.22f;Collider mc=moon.GetComponent<Collider>();if(mc!=null)mc.enabled=false;Renderer mr=moon.GetComponent<Renderer>();if(mr!=null)mr.material.color=Color.Lerp(color,Color.black,.25f);}}else if(variant==2){for(int i=0;i<5;i++){GameObject spike=GameObject.CreatePrimitive(PrimitiveType.Cube);spike.name="DF_FinalPlanetCrown";spike.transform.SetParent(root.transform,false);float sa=i*Mathf.PI*2f/5f;spike.transform.localPosition=new Vector3(Mathf.Cos(sa)*.72f,.88f,Mathf.Sin(sa)*.72f);spike.transform.localScale=new Vector3(.1f,.72f,.1f);spike.transform.localRotation=Quaternion.Euler(18,i*72f,18);Collider sc=spike.GetComponent<Collider>();if(sc!=null)sc.enabled=false;Renderer sr=spike.GetComponent<Renderer>();if(sr!=null)sr.material.color=Color.Lerp(color,Color.white,.45f);}}for(int i=0;i<2;i++){GameObject orbitRing=GameObject.CreatePrimitive(PrimitiveType.Cylinder);orbitRing.name="DF_PlanetOrbitRing";orbitRing.transform.SetParent(root.transform,false);float os=2.25f+i*.34f;orbitRing.transform.localScale=new Vector3(os,.012f,os);orbitRing.transform.localRotation=Quaternion.Euler(variant==1?55f+i*17f:70f-i*14f,i*33f,12f+i*21f);Collider oc=orbitRing.GetComponent<Collider>();if(oc!=null)oc.enabled=false;Renderer or=orbitRing.GetComponent<Renderer>();if(or!=null)or.material.color=Color.Lerp(color,Color.white,.18f+i*.12f);}GameObject core=GameObject.CreatePrimitive(PrimitiveType.Sphere);core.name="DF_PlanetCore";core.transform.SetParent(root.transform,false);core.transform.localScale=Vector3.one*.46f;Collider cc=core.GetComponent<Collider>();if(cc!=null)cc.enabled=false;Renderer cr=core.GetComponent<Renderer>();if(cr!=null)cr.material.color=Color.Lerp(color,Color.white,.62f);GameObject beacon=GameObject.CreatePrimitive(PrimitiveType.Cylinder);beacon.name="DF_PlanetGroundBeacon";if(world!=null)beacon.transform.SetParent(world.transform,true);beacon.transform.position=new Vector3(p.x,.04f,p.z);beacon.transform.localScale=new Vector3(variant==2?2.8f:2.35f,.018f,variant==2?2.8f:2.35f);Collider bc=beacon.GetComponent<Collider>();if(bc!=null)bc.enabled=false;Renderer br=beacon.GetComponent<Renderer>();if(br!=null)br.material.color=Color.Lerp(color,Color.white,.2f);Health h=root.AddComponent<Health>();h.Configure(hp);DimensionPlanet planet=root.AddComponent<DimensionPlanet>();planet.Initialize(type);PlanetPulseAttack pulse=root.AddComponent<PlanetPulseAttack>();if(type==PlanetBuffType.Guard){pulse.enabled=false;root.AddComponent<PlanetMeteorShower>();}}
}
}
